using System.Threading.Channels;

var auftraege = Channel.CreateUnbounded<string>();

var drucker = Task.Run(async () =>
{
  await foreach (var job in
      auftraege.Reader.ReadAllAsync())
    Console.WriteLine($"drucke {job}");
});

foreach (var d in new[] { "a.pdf", "b.pdf" })
  await auftraege.Writer.WriteAsync(d);
auftraege.Writer.Complete();  // Stopp-Signal
await drucker;
// drucke a.pdf
// drucke b.pdf

