class Broker
{
  readonly Dictionary<string,
    List<Action<string>>> abos = new();

  public void Subscribe(string topic,
                        Action<string> h)
  {
    if (!abos.TryGetValue(topic, out var l))
      abos[topic] = l = new();
    l.Add(h);
  }

  public void Publish(string topic, string msg)
  {
    if (abos.TryGetValue(topic, out var l))
      foreach (var h in l) h(msg);
  }
}

using System.Net.Http.Json;

// Server: eine "entfernte Funktion"
var app = WebApplication.Create();
app.MapPost("/rpc/notenschnitt",
  (int[] noten) => noten.Average());
app.Urls.Add("http://127.0.0.1:5001");
await app.StartAsync();

// Client: der Stub sieht aus wie lokal
var stub = new NotenStub(new HttpClient {
  BaseAddress = new("http://127.0.0.1:5001") });
Console.WriteLine(
  await stub.SchnittAsync([1, 2, 2]));
// 1.6666666666666667
try { await stub.SchnittAsync([]); }
catch (HttpRequestException e)
{ Console.WriteLine(e.StatusCode); }
// InternalServerError
await app.StopAsync();

class NotenStub(HttpClient http)
{
  public async Task<double> SchnittAsync(
    int[] noten)
  {
    var r = await http.PostAsJsonAsync(
      "/rpc/notenschnitt", noten);
    r.EnsureSuccessStatusCode();
    return await r.Content
      .ReadFromJsonAsync<double>();
  }
}

// noten.proto
syntax = "proto3";
service Noten {
  rpc Schnitt (NotenListe)
      returns (Ergebnis);
}
message NotenListe {
  repeated int32 noten = 1; }
message Ergebnis { double schnitt = 1; }

// C#: Basisklasse wird generiert
using Grpc.Core;
class NotenService : Noten.NotenBase
{
  public override Task<Ergebnis> Schnitt(
    NotenListe req, ServerCallContext ctx)
    => Task.FromResult(new Ergebnis
       { Schnitt = req.Noten.Average() });
}
